func ptrBillingTransferRunItem(p unsafe.Pointer, c int32) any {
	r := (*billingtransfer.BillingTransferRunItem)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RunID))
	case 4:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 5:
		return (*int64)(unsafe.Pointer(&r.Sequence))
	case 6:
		return &r.ProNumber
	case 7:
		return (*string)(unsafe.Pointer(&r.Status))
	case 8:
		return (*string)(unsafe.Pointer(&r.FailureCode))
	case 9:
		return &r.ErrorMessage
	case 10:
		return &r.MarkedReadyToInvoice
	case 11:
		return (*string)(unsafe.Pointer(&r.BillingQueueItemID))
	case 12:
		return &r.BillingQueueNumber
	case 13:
		return (*string)(unsafe.Pointer(&r.BillingQueueStatus))
	case 14:
		return &r.MissingRequirements
	case 15:
		return &r.ValidationFailures
	case 16:
		return &r.ProcessedAt
	case 17:
		return &r.CreatedAt
	case 18:
		return &r.UpdatedAt
	}
	return nil
}

func valueBillingTransferRunItem(p unsafe.Pointer, c int32) any {
	r := (*billingtransfer.BillingTransferRunItem)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RunID)
	case 4:
		return string(r.ShipmentID)
	case 5:
		return int64(r.Sequence)
	case 6:
		if r.ProNumber == "" {
			return nil
		}
		return r.ProNumber
	case 7:
		return string(r.Status)
	case 8:
		if r.FailureCode == "" {
			return nil
		}
		return string(r.FailureCode)
	case 9:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 10:
		return r.MarkedReadyToInvoice
	case 11:
		if r.BillingQueueItemID == "" {
			return nil
		}
		return string(r.BillingQueueItemID)
	case 12:
		if r.BillingQueueNumber == "" {
			return nil
		}
		return r.BillingQueueNumber
	case 13:
		if r.BillingQueueStatus == "" {
			return nil
		}
		return string(r.BillingQueueStatus)
	case 14:
		if r.MissingRequirements == nil {
			return keel.EmptyJSONArray
		}
		return r.MissingRequirements
	case 15:
		if r.ValidationFailures == nil {
			return keel.EmptyJSONArray
		}
		return r.ValidationFailures
	case 16:
		if r.ProcessedAt == nil {
			return nil
		}
		return *r.ProcessedAt
	case 17:
		return r.CreatedAt
	case 18:
		return r.UpdatedAt
	}
	return nil
}

